/** Greets a name, or the world when the name is blank. */
export function greet(name: string): string {
  return `Hello, ${name.trim() || 'world'}!`;
}

input.new_string:
/** Greets a name, or the world when the name is blank. */
export function greet(name: string, options: { shout?: boolean } = {}): string {
  const greeting = `Hello, ${name.trim() || 'world'}!`;
  return options.shout ? greeting.toUpperCase() : greeting;
}

test('greets the world when blank', () => expect(greet('  ')).toBe('Hello, world!'));
test('shouts the greeting', () => expect(greet('Ada', { shout: true })).toBe('HELLO, ADA!'));
test('shouts the world when blank', () => expect(greet('  ', { shout: true })).toBe('HELLO, WORLD!'));
test('defaults to not shouting', () => expect(greet('Ada')).toBe('Hello, Ada!'));

